pub(crate) fn preflight_reserve(
    args: &cli::ServeArgs,
    config: &ModelConfig,
    free_mem: usize,
) -> Result<ReservePreflight> {
    let h_state_bytes = config.ssm_h_state_bytes();
    let conv_state_bytes = config.ssm_conv_state_bytes();

let decode_ring_slots = if std::env::var("ATLAS_SSM_RESERVE_RING_FULL").is_ok() {
    if config.num_ssm_layers() > 0 {
        atlas_kernels::DECODE_ROLLBACK_RING_SLOTS
    } else {
        0
    }
} else {
    spark_model::ssm_reserve::decode_rollback_ring_slots(
        config.num_ssm_layers(),
        args.speculative || args.dflash,
    )
    .slots
};
let ssm_snapshot_bytes = (args.ssm_cache_slots + decode_ring_slots * args.max_batch_size)
    * config.num_ssm_layers()
    * (h_state_bytes + conv_state_bytes);
// Same predicate as the pool term: DFlash IS a speculative serve and
// pays the same graph/JIT/scratch overheads the 4 GB headroom exists for.
let cuda_headroom: usize = if spec_on_pool {
    4 * 1024 * 1024 * 1024
} else {
    512 * 1024 * 1024
};
let gdn_two_phase_bytes: usize = {
    let key_dim = config.linear_num_key_heads * config.linear_key_head_dim;
    let value_dim = config.linear_num_value_heads * config.linear_value_head_dim;
    let nv = config.linear_num_value_heads;
    let conv_dim = key_dim * 2 + value_dim;
    if conv_dim > 0 && config.num_ssm_layers() > 0 {
        let sl = max_batch_tokens_pre;
        sl * conv_dim * 2 + sl * nv * 2 * 4 + sl * value_dim * 2 + sl * value_dim * 2
    } else {
        0
    }
};
let inference_reserve: usize = ssm_pool_bytes
    + ssm_h_stage_bytes
    + ssm_replay_ring
    + ssm_snapshot_bytes
    + gdn_two_phase_bytes
    + cuda_headroom;

/// Per-layer SSM hidden state size in bytes (FP32).
/// Dispatches on SSM architecture: Mamba-2 vs GDN, using config fields.
pub fn ssm_h_state_bytes(&self) -> usize {
    if self.mamba_num_heads > 0 && self.mamba_head_dim > 0 {
        // Mamba-2: h[num_heads, head_dim, state_size] FP32
        self.mamba_num_heads * self.mamba_head_dim * self.ssm_state_size * 4
    } else {
        // GDN: h[nv, vd, kd] FP32
        self.linear_num_value_heads * self.linear_value_head_dim * self.linear_key_head_dim * 4
    }
}

/// Per-layer SSM conv state size in bytes (FP32).
pub fn ssm_conv_state_bytes(&self) -> usize {
    let d_conv = self.linear_conv_kernel_dim;
    if self.mamba_num_heads > 0 && self.mamba_head_dim > 0 {
        // Mamba-2: conv: [d_xBC, d_conv] FP32
        self.mamba2_d_xbc() * d_conv * 4
    } else {
        // GDN: conv: [conv_dim, d_conv] FP32
        let conv_dim = self.linear_num_key_heads * self.linear_key_head_dim * 2
            + self.linear_num_value_heads * self.linear_value_head_dim;
        conv_dim * d_conv * 4
    }
}

let ring = crate::ssm_reserve::decode_rollback_ring_slots(
    ssm_pool.num_ssm_layers,
    use_speculative,
);
if let Some(reason) = ring.skip_reason {
    let per_seq = (ssm_pool.h_bytes + ssm_pool.conv_bytes)
        * ssm_pool.num_ssm_layers
        * atlas_kernels::DECODE_ROLLBACK_RING_SLOTS;
    tracing::info!(
        "SSM decode-rollback ring: SKIPPED ({}) — the ring's save/rollback \
         path only runs on plain decode with watchdogs enabled. Saves {:.1} GB \
         ({} seqs x {} slots x full SSM blob). If plain-decode loop re-steer is \
         ever reached it fail-opens to decline; ATLAS_SSM_DECODE_RING=1 \
         force-restores the ring.",
        reason,
        (per_seq * max_batch_size) as f64 / 1e9,
        max_batch_size,
        atlas_kernels::DECODE_ROLLBACK_RING_SLOTS,
    );
}
let decode_ring_slots = ring.slots;
let ssm_snapshots = SsmSnapshotPool::new(
    ssm_cache_slots,
    ssm_pool.h_bytes,
    ssm_pool.conv_bytes,
    ssm_pool.num_ssm_layers,
    decode_ring_slots,
    max_batch_size,
    // Last-token hidden snapshot: post-final-norm `norm_output` is
    // BF16 (`hidden_size` elements). Used to emit exact-hit logits
    // without re-running the last token through the SSM layers.
    config.hidden_size * 2,
    gpu.as_ref(),
)?;

let _d_conv = config.linear_conv_kernel_dim;

let h_bytes = config.ssm_h_state_bytes();
let h_stored_bytes = crate::ssm_reserve::ssm_h_stored_bytes(h_bytes, h_f16_pool);
let conv_bytes = config.ssm_conv_state_bytes();
let num_ssm_layers = config.num_ssm_layers();

// Reserve one extra slot at index `max_slots` as a dedicated
// dummy used by `decode_batch` / `mixed_forward` padding (see
// `dummy_slot()` below). Without this, pad positions write to
// pool slot indices `n..padded_n` which can collide with
// claimed slots if the scheduler invariant ("active sequences
// occupy contiguous slots [0..n)") is ever broken — silent SSM
// state corruption. Costs `(h_bytes + conv_bytes) *
// num_ssm_layers` extra GPU memory (~kilobytes per pool).
let total_slots = max_slots + 1;

let mut owned_allocations = Vec::new();
let mut h_intermediate_pools = Vec::new();
let mut conv_intermediate_pools = Vec::new();
let mut h_checkpoint_pools = Vec::new();
let mut conv_checkpoint_pools = Vec::new();

let (h_state_pools, allocations) =
    alloc_layer_pools(gpu, num_ssm_layers, total_slots * h_stored_bytes)?;
owned_allocations.extend(allocations);
let (conv_state_pools, allocations) =
    alloc_layer_pools(gpu, num_ssm_layers, total_slots * conv_bytes)?;
owned_allocations.extend(allocations);

pub(super) fn new(
    num_slots: usize,
    h_bytes: usize,
    conv_bytes: usize,
    num_ssm_layers: usize,
    decode_ring_slots: usize,
    decode_max_seqs: usize,
    hidden_bytes: usize,
    gpu: &dyn GpuBackend,
) -> Result<Self> {
    let decode_enabled = num_ssm_layers > 0 && decode_ring_slots > 0 && decode_max_seqs > 0;
    let marconi_enabled = num_ssm_layers > 0 && num_slots > 0;

    if !marconi_enabled && !decode_enabled {
        return Ok(Self {
            h_snapshots: Vec::new(),
            conv_snapshots: Vec::new(),
            free_slots: Mutex::new(Vec::new()),
            num_slots: 0,
            h_bytes,
            conv_bytes,
            num_ssm_layers,
            session_tags: Mutex::new(std::collections::HashMap::new()),
            aux_blobs: Mutex::new(std::collections::HashMap::new()),
            decode_h_snapshots: Vec::new(),
            decode_conv_snapshots: Vec::new(),
            decode_ring_slots: 0,
            decode_max_seqs: 0,
            hidden_snapshot: DevicePtr::NULL,
            hidden_bytes,
            slot_has_hidden: Mutex::new(std::collections::HashSet::new()),
            h_f16_to_f32_k: KernelHandle(0),
            h_f32_to_f16_k: KernelHandle(0),
            spill_staging: Default::default(),
        });
    }

    let mut h_snapshots = Vec::new();
    let mut conv_snapshots = Vec::new();
    let mut hidden_snapshot = DevicePtr::NULL;
    if marconi_enabled {
        for _ in 0..num_ssm_layers {
            h_snapshots.push(gpu.alloc(num_slots * h_bytes)?);
            conv_snapshots.push(gpu.alloc(num_slots * conv_bytes)?);
        }
        hidden_snapshot = gpu.alloc(num_slots * hidden_bytes)?;
    }

    let mut decode_h_snapshots = Vec::new();
    let mut decode_conv_snapshots = Vec::new();
    let decode_region = if decode_enabled {
        decode_max_seqs * decode_ring_slots
    } else {
        0
    };
    if decode_enabled {
        for _ in 0..num_ssm_layers {
            decode_h_snapshots.push(gpu.alloc(decode_region * h_bytes)?);
            decode_conv_snapshots.push(gpu.alloc(decode_region * conv_bytes)?);
        }

pub fn ssm_pool_reserve_bytes(
    max_batch_size: usize,
    h_blob_bytes: usize,
    conv_blob_bytes: usize,
    spec_on: bool,
    num_drafts: usize,
    mtp_state_slots: usize,
    uniform_verify: bool,
    h_f16_pool: bool,
    rollback: SsmRollbackMode,
) -> usize {
    let h_blob_bytes = ssm_h_stored_bytes(h_blob_bytes, h_f16_pool);
    let blob = h_blob_bytes + conv_blob_bytes;
    let base = max_batch_size * blob;
    if !spec_on {
        return base;
    }
    let verify: usize = (0..mtp_state_slots)
        .map(|slot| match rollback {
            SsmRollbackMode::Snapshot => {
                verify_slot_h_intermediates(slot, num_drafts, uniform_verify) * h_blob_bytes
                    + (num_drafts + 1) * conv_blob_bytes
                    + blob
            }
            // Replay keeps ONLY the pre-verify checkpoint blob per slot —
            // partial accepts are reconstructed by replaying the accepted
            // tokens from it, so no per-token h/conv snapshots exist. The
            // verify-window input ring is a SEPARATE term
            // ([`ssm_replay_ring_bytes`]) because it is sized by activation
            // rows, not state blobs.
            SsmRollbackMode::Replay => blob,
        })
        .sum();
    base + verify
}

/// SSM verify-rollback mode (`--ssm-rollback-mode`, EXPERIMENTAL scaffold).
///
/// * `Snapshot` (the serve default, explicit in the CLI): every verify arm
///   writes per-token h/conv state snapshots; a partial accept restores from

fn watchdogs_disabled_from_value(value: Option<&str>) -> bool {
    value
        .map(|v| {
            let v = v.trim().to_ascii_lowercase();
            v == "1" || v == "true"
        })
        .unwrap_or(false)
}

fn decode_rollback_ring_slots_with(
    num_ssm_layers: usize,
    use_speculative: bool,
    ring_override: Option<&str>,
    watchdogs_disabled: bool,
) -> DecodeRingDecision {
    if num_ssm_layers == 0 {
        return DecodeRingDecision {
            slots: 0,
            skip_reason: None,
        };
    }
    match ring_override {
        Some("1") => DecodeRingDecision {
            slots: atlas_kernels::DECODE_ROLLBACK_RING_SLOTS,
            skip_reason: None,
        },
        Some("0") => DecodeRingDecision {
            slots: 0,
            skip_reason: None,
        },
        _ if use_speculative || watchdogs_disabled => DecodeRingDecision {
            slots: 0,
            skip_reason: Some(if use_speculative {
                "speculative decode active"
            } else {
                "watchdogs disabled"
            }),
        },
        _ => DecodeRingDecision {
            slots: atlas_kernels::DECODE_ROLLBACK_RING_SLOTS,
            skip_reason: None,
        },
    }
}
