/// Load a quantized weight from FP8 block-scaled data: FP8→BF16→NVFP4.
///
/// `n` and `k` are the logical weight dimensions (e.g. [inter, hidden] for gate_proj).
pub(crate) fn quantized_from_fp8(
    store: &WeightStore,
    prefix: &str,
    n: usize,
    k: usize,
    gpu: &dyn GpuBackend,
    absmax_k: spark_runtime::gpu::KernelHandle,
    quantize_k: spark_runtime::gpu::KernelHandle,
    stream: u64,
) -> Result<QuantizedWeight> {
    let bf16 = dequant_fp8_blockscaled_to_bf16(store, prefix, gpu)?;
    let result = quantize_to_nvfp4(&bf16, n, k, gpu, absmax_k, quantize_k, stream)?;
    // Free the BF16 intermediate — only the NVFP4 result is needed.
    gpu.free(bf16.weight)?;
    Ok(result)

// Phase 2: Quantize
let t = std::time::Instant::now();
let packed_buf = gpu.alloc(n * k / 2)?;
let scale_buf = gpu.alloc(n * k / 16)?;

// Dense FFN instead of MoE. Native FP8 checkpoints (single-GPU)
// load gate/up/down directly as block-scaled `Fp8Weight` and
// dispatch w8a16 — no NVFP4 requant. TP>1 still uses the NVFP4
// path (FP8 FFN sharding is a follow-up).
let ffn_fp8 = dense_fp8_enabled()
    && config.tp_world_size.max(1) == 1
    && matches!(variant, Nvfp4Variant::Fp8Dequanted)
    && proj_is_native_fp8(store, &format!("{lp}.mlp.gate_proj"));
// Always load the NVFP4 weights so every dispatch path (incl. the
// batched spec-decode forward_k2/k3 paths that have no FP8 branch)
// has a valid weight to fall back to — a null NVFP4 weight under a
// w4a16 dispatch is the CUDA-700-at-concurrency bug. When native
// FP8 is enabled we overlay the block-scaled FP8 weights on top;
// the hot forward / forward_prefill paths then use FP8, the rare
// batched paths fall back to real NVFP4.

let qkvz_f = concat_fp8_block_scaled(&qkv_f, &z_f, h, gpu)?;
// The concat copied both grids; free the per-projection
// scale allocs (weight bytes are store-owned, not freed).
gpu.free(qkv_f.row_scale)?;
gpu.free(z_f.row_scale)?;
let ssm = SsmWeights {
    in_proj_qkvz: DenseWeight {
        weight: spark_runtime::gpu::DevicePtr::NULL,
    },
    in_proj_ba: ba_dense,
    conv1d,
    a_log,
    dt_bias,
    norm,
    out_proj: crate::weight_map::QuantizedWeight::null(),
};
let mut layer = Qwen3SsmLayer::new_sequential(
    input_norm,
    ssm,
    post_attn_norm,
    ffn,
    None,
    None,
    None,
    config,
    gpu,
)?;
layer.set_fp8_decode_weights(Some(qkvz_f), Some(out_f));

self.ensure_nvfp4_mmq_weight(
    &self.fp4mmq_gate,
    gpu,
    &self.weights.gate_proj,
    inter,
    h,
    stream,
)?;
self.ensure_nvfp4_mmq_weight(
    &self.fp4mmq_up,
    gpu,
    &self.weights.up_proj,
    inter,
    h,
    stream,
)?;
let down_mmq = std::env::var_os("ATLAS_NO_FFN_NVFP4_MMQ_DOWN").is_none();
if down_mmq {
    self.ensure_nvfp4_mmq_weight(
        &self.fp4mmq_down,
        gpu,
        &self.weights.down_proj,
        h,
        inter,
        stream,
    )?;
}
gpu.synchronize(stream)?;
// Free the dead transposed copies (prefill for those projections now runs on the
// MMQ arm; decode reads the non-transposed originals). down_proj_t is freed only
// when the down A/B gate is on.
let mut down_t = if down_mmq {
    Some(&mut self.weights.down_proj_t)
} else {
    None
};
let mut freed = 0usize;
for wt in [&mut self.weights.gate_proj_t, &mut self.weights.up_proj_t]
    .into_iter()
    .chain(down_t.take())

/// Ensure the block_nvfp4 copy of one NVFP4 projection exists (raw repack of the
/// checkpoint's packed E2M1 `[N, K/2]` + E4M3 `[N, K/16]` scales — zero numerics;
/// scale2 folded at the SiLU-mul). Cached in `cell` for process lifetime.
fn ensure_nvfp4_mmq_weight(
    &self,
    cell: &std::sync::OnceLock<Fp4MmqWeight>,
    gpu: &dyn GpuBackend,
    src: &QuantizedWeight,
    n: u32,
    k: u32,
    stream: u64,
) -> Result<Fp4MmqWeight> {
    if let Some(w) = cell.get() {
        return Ok(*w);
    }
    let w = gpu.alloc(ops::nvfp4_mmq_weight_bytes(n, k))?;
    ops::nvfp4_mmq_repack(
        gpu,
        self.nvfp4_repack_k,
        src.weight,
        src.weight_scale,
        w,
        n,
        k,
        stream,
    )?;
    let built = Fp4MmqWeight { w };
    if let Err(dup) = cell.set(built) {
        gpu.synchronize(stream)?;
        let _ = gpu.free(dup.w);
    }
    Ok(*cell.get().expect("fp4mmq weight cell set above"))

// ── gpu_memory_utilization as fraction of TOTAL GPU memory ──
//
// User-facing contract (matches vLLM / sparkrun convention):
//   total_memory × gpu_memory_utilization = hard ceiling on everything
//   this process consumes (weights + buffers + KV cache + reserves).
//
// KV cache gets whatever remains inside that ceiling after deducting
// prior allocations (model weights, buffer arena, CUDA context/driver)
// and the inference reserve (SSM state pools, CUDA headroom).  A safety
// clamp ensures we never exceed what the device can physically provide
// right now (handles external memory pressure on shared-memory /
// unified-memory systems like GB10).
let total_mem = gpu.total_memory()?;
let actual_free = gpu.free_memory()?;
let gib = |b: usize| b as f64 / (1024.0 * 1024.0 * 1024.0);
let mut used_so_far = total_mem.saturating_sub(actual_free);

} else if let Some(ledger_live) = gpu.live_bytes() {
    // AUTO via LEDGER: what this backend actually allocated and still
    // holds. Sanity-gate mirrors the free-delta path: the ledger can
    // only be a subset of total used (it can't see co-tenants), so a
    // value above `used_so_far` means the ledger and the device
    // disagree — fall through to raw rather than oversize the pool.
    if ledger_live > 0 && ledger_live <= used_so_far {
        tracing::info!(
            "KV budget self-relative (ledger): Atlas-own {:.1} GB live in \
             the alloc ledger; {:.1} GB of co-tenant/page-cache use \
             excluded (set ATLAS_KV_EXTERNAL_RESERVE_GB to override)",
            gib(ledger_live),
            gib(used_so_far - ledger_live),
        );
        used_so_far = ledger_live;

// Every layer has taken the pointers it needs; hand the ledger to the model
// so `teardown` can free the weights. Dropping it here — which is what used
// to happen — orphaned the memory: live, referenced by the layers, with
// nothing owning the ability to release it.
model.adopt_weight_store(store);

// ── Allocation attribution, once, at the end of load ──
// Everything the serve will hold is allocated by now: weights, KV, the SSM
// pools, the Marconi snapshots, the arenas, the vision encoder. This is
// the only point where the ledger describes the STEADY STATE rather than
// some midpoint of the build.
//
// It exists because the KV-budget line above reports `pre-KV` as one
// opaque number, and on a 27B that number is ~59 GB against 22 GB of
// weights — the rest was unattributable until the ledger learned sizes.
// Logged at INFO, not behind a flag: every OOM and every mis-sized-pool
// investigation so far has begun by wanting exactly this table, and a
// once-per-load table is not a cost worth flagging off.
if let Some(report) = model.gpu_backend().alloc_report(12, 64) {
    for line in report.lines() {
        tracing::info!("{line}");
    }

// 7. Create scheduler channel + spawn scheduler
spark_runtime::progress::phase(9, "scheduler");
let (request_tx, request_rx) = mpsc::channel::<InferenceRequest>(args.max_num_seqs);
// LoRA adapter-rotation control channel (POST /v1/lora/active). Small: it
// carries only control messages, applied one-at-a-time at quiescence.
let (rotation_tx, rotation_rx) = mpsc::channel::<scheduler::LoraRotation>(8);

if g.requests.is_empty() || !policy.should_prefill(&timings) {
    return Vec::new();
}

// Account for both active and in-progress prefilling sequences.
let cap = max_batch_size.saturating_sub(active.len() + prefilling.len());

let infos: Vec<PendingRequestInfo> = g
    .requests
    .iter()
    .enumerate()
    .map(|(i, req)| PendingRequestInfo {
        prompt_len: req.prompt_len(),
        index: i,
    })
    .collect();
let selected = policy.select_prefills(&infos, cap);

/// Maximum concurrent sequences.
#[arg(long, default_value_t = 128)]
pub max_num_seqs: usize,

/// Maximum concurrent sequences batched into one GPU decode step.
#[arg(long, default_value_t = 8)]
pub max_batch_size: usize,

/// Number of SSM state snapshot slots for Marconi prefix caching.
/// Each slot stores SSM h_state + conv_state for all SSM layers,
/// enabling full prefix skip (KV + SSM) on cache hits.
/// 0 = disabled. 16 = recommended for repeated-prefix and multi-turn workloads.
/// Intermediate checkpoints (--ssm-checkpoint-interval) require extra slots:
/// ~(max_context / checkpoint_interval_tokens) per cached sequence.
#[arg(long, default_value_t = 16)]
pub ssm_cache_slots: usize,

let top: Vec<String> = rows
    .iter()
    .take(5)
    .map(|(site, (b, n))| {
        format!("{site} ({:.1} MB x{n})", *b as f64 / (1024.0 * 1024.0))
    })
    .collect();
tracing::warn!(
    "sweep: {count} allocation(s) totalling {:.2} GB had no owner; \
     largest sites: {}",
    bytes as f64 / 1e9,
    top.join(", ")
);

/// Sum of K+V block bytes across all layers for one block slot.
/// Accounts for mixed dtypes when layer_dtypes is set AND asym K/V splits.
pub fn block_bytes_kv_all_layers(&self) -> usize {
    (0..self.num_layers)
        .map(|i| self.k_block_bytes_for_layer(i) + self.v_block_bytes_for_layer(i))
        .sum()

/// Compute how many blocks can fit given available GPU memory.
/// Accounts for mixed dtypes when layer_dtypes is set.
pub fn compute_num_blocks(config: &KvCacheConfig, available_bytes: usize) -> Result<usize> {
    let bytes_per_block = config.block_bytes_kv_all_layers();
    if bytes_per_block == 0 {
        bail!("KV cache block size is zero");
    }
    Ok(available_bytes / bytes_per_block)
}
